package com.mamtrex.hospital.patient; import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.shared.NotFoundException; import org.springframework.dao.DuplicateKeyException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDate; import java.util.*; @Service @Transactional public class PatientService { private final PatientRepository repo; private final AuditService audit; public PatientService(PatientRepository r,AuditService a){repo=r;audit=a;} public Patient create(String mrn,String name,LocalDate dob,String sex,String phone,String email,String nationalId,String address){repo.findByMedicalRecordNumber(mrn).ifPresent(existing->{throw new DuplicateKeyException("Medical record number already exists");});var p=repo.save(new Patient(mrn,name,dob,sex,phone,email,nationalId,address));audit.record("CREATE","Patient",p.getId().toString(),mrn);return p;} @Transactional(readOnly=true) public Patient get(UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("Patient not found: "+id));} @Transactional(readOnly=true) public List<Patient> list(String q){return q==null||q.isBlank()?repo.findAll():repo.findByFullNameContainingIgnoreCase(q);} public Patient update(UUID id,String name,String phone,String email,String address){var p=get(id);p.update(name,phone,email,address);audit.record("UPDATE","Patient",id.toString(),"profile");return p;} }
